'use strict'

/**
 * Unpipe a stream from all of its destinations.
 *
 * Works with modern Readable streams (which expose `unpipe()`) and with
 * legacy streams that were piped via the classic `Stream.prototype.pipe`,
 * which has no `unpipe()` and instead registers a `cleanup` listener per
 * destination on the source's `close` event.
 *
 * @param {import('stream').Stream} stream
 */
function unpipe (stream) {
  if (!stream) {
    throw new TypeError('argument stream is required')
  }

  if (typeof stream.unpipe === 'function') {
    // Called with no destination, this detaches every piped destination.
    stream.unpipe()
    return
  }

  // Legacy stream: only act if it is actually piped somewhere.
  if (!hasPipeDataListeners(stream)) {
    return
  }

  // Snapshot first, since invoking cleanup removes listeners as we iterate.
  for (const listener of stream.listeners('close')) {
    if (listener.name === 'cleanup' || listener.name === 'onclose') {
      if (listener.name === 'cleanup') listener.call(stream)
    }
  }
}

function hasPipeDataListeners (stream) {
  return stream.listeners('data').some((l) => l.name === 'ondata')
}

module.exports = unpipe
EOF

